      ro: ["Munții Kyrenia", "Vedere spre coasta de nord", "Calcar", "Traseu de drumeții"],
      en: ["Kyrenia Mountains", "North coast view", "Limestone", "Hiking route"],
      es: ["Montañas de Kyrenia", "Vista de la costa norte", "Roca caliza", "Ruta de senderismo"],
      pt: ["Montanhas de Kyrenia", "Vista da costa norte", "Rocha calcária", "Rota de caminhada"],
